from ...base.client import BaseClient
from typing import TypedDict, Unpack


class PollRespondersKwargs(TypedDict):
    newest: str
    oldest: str


class PollsMethods(BaseClient):
    """
    Методы группы 'Опросы' из https://im-docs.corp.mail.ru/
    """

    async def rapi_poll_stop(self, _id: str) -> dict:
        """
        Остановить опрос
        :param _id: ID опроса
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/poll/stop",
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"id": _id},
            },
        )

    async def rapi_poll_get(self, _id: str, subscribe: bool = True) -> dict:
        """
        Детальное описание механики работы подписки
        в описании запроса /poll/subscribe.
        :param _id: ID опроса
        :param subscribe: Флаг подписки
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/poll/get",
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"id": _id, "subscribe": subscribe},
            },
        )

    async def rapi_poll_vote(self, _id: str, answerId: str) -> dict:
        """
        Выбрать вариант ответа в опросе
        :param _id: ID опроса
        :param answerId: ID ответа
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/poll/vote",
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"id": _id, "answerId": answerId},
            },
        )

    async def rapi_poll_revoke(self, _id: str) -> dict:
        """
        Отменить выбранный в опросе вариант
        :param _id: ID опроса
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/poll/revoke",
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"id": _id},
            },
        )

    async def rapi_poll_subscribe(self, _id: str) -> dict:
        """
        Обновления после подписки будут отправляться клиенту
        эвентом pollUpdate.
        Подписка истекает автоматически через определенный интервал времени.
        На данный момент это 60 секунд.
        Клиент, при необходимости, должен переподписываться на обновления сам.
        Подписку стоит обновлять заранее. При длительности 60 секунд,
        переподписываться надо через 40 секунд, чтобы покрыть
        потенциальную задержку на обработку запроса подписки и
        не пропустить обновления.
        Чтобы учесть случай рассинхрона интервала переподписки между сервером
        и клиентом, можно выполнять переподписку методом /poll/get,
        получая свежие данные в момент подписки. При такой схеме
        данный запрос не используется.
        На данный момент, переподписка через /poll/get
        является наиболее надежным вариантом.
        :param _id: ID опроса
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/poll/subscribe",
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"id": _id},
            },
        )

    async def rapi_poll_responders(
        self, poll_id: str, answer_id: str, limit: int = 10, **kwargs: Unpack[PollRespondersKwargs]
    ):
        """
        Получение списка проголосовавших

        В примере запроса указаны два поля - newerThan & olderThan.
        На самом деле нужно указывать только одно из них.
        При листании вверх (новые ответы) - newerThan.
        При листании вниз (прошлые ответы) - olderThan.
        При отправке двух полей в одном запросе будет возвращена
        ошибка валидации (40000).
        param newerThan:
        param olderThan:
        """
        if "olderThan" not in kwargs and "newerThan" not in kwargs:
            raise ValueError("One of parametrs must be passed")
        else:
            return await self.post(
                "rapi/poll/responders",
                json={
                    "aimsid": self.aimsid,
                    "reqId": self.getReqId(),
                    "params": {
                        "id": poll_id,
                        "answerId": answer_id,
                        "limit": limit,
                        **kwargs,
                    },
                },
            )
